const getUpcomingEvents = (campusId, sourceEvents = events) => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  return sourceEvents.filter((item) => (!campusId || item.campusId === campusId) && new Date(`${item.endDate}T23:59:59`) >= today).sort((a, b) => a.startDate.localeCompare(b.startDate));
};
