              <Pressable style={styles.myGicCampusCard} onPress={() => openCampus(selected)}><View style={styles.myGicCampusIcon}><Text style={{fontSize:23}}>{selected.flag}</Text></View><View style={{flex:1}}><Text style={styles.listTitle}>{selected.name}</Text><Text style={styles.listText}>{selected.address}</Text><Text style={styles.campusTime}>{selected.services[0].time}</Text></View><Ionicons name="chevron-forward" size={18} color="#9aa0b5" /></Pressable>
