            <Pressable style={styles.settingsRow} onPress={() => external('https://sermon-api.vercel.app/privacy-policy.html')}><View style={styles.smallIcon}><Ionicons name="shield-checkmark-outline" size={20} color="#5965f8" /></View><View style={{flex:1}}><Text style={styles.listTitle}>Privacy policy</Text><Text style={styles.listText}>How this app handles information you share.</Text></View><Ionicons name="open-outline" size={17} color="#9aa0b5" /></Pressable>
