            <Pressable style={styles.settingsRow} onPress={() => external(YOUTUBE_CHANNEL_URL)}><View style={styles.smallIcon}><Ionicons name="logo-youtube" size={20} color="#5965f8" /></View><View style={{flex:1}}><Text style={styles.listTitle}>GIC YouTube</Text><Text style={styles.listText}>Watch sermons and church broadcasts.</Text></View><Ionicons name="open-outline" size={17} color="#9aa0b5" /></Pressable>
