            <Pressable style={styles.listCard} onPress={() => open('Weekly Word')}><View style={styles.smallIcon}><Ionicons name="book-outline" size={20} color="#5965f8" /></View><View style={{flex:1}}><Text style={styles.listTitle}>Weekly Word</Text><Text style={styles.listText}>Encouragement, sermon notes, and updates.</Text></View><Ionicons name="chevron-forward" size={18} color="#9aa0b5" /></Pressable>
