              <Pressable style={styles.directionsButton} onPress={() => campus.online ? external(SITE) : openDirections(campus.map)}><Text style={styles.directionsText}>{campus.online ? 'CONNECT WITH GIC' : 'GET DIRECTIONS'}</Text><Ionicons name={campus.online ? 'arrow-forward' : 'navigate-outline'} size={16} color="#1478b7" /></Pressable>
