            <View style={styles.sermonSearch}><Ionicons name="search-outline" size={18} color="#8389a0" /><TextInput style={styles.sermonSearchInput} value={ministrySearch} onChangeText={setMinistrySearch} placeholder="Search ministries" placeholderTextColor="#969bad" returnKeyType="search" /></View>
