            {(() => { const query = ministrySearch.trim().toLowerCase(); const visibleMinistries = ministries.filter((item) => (ministryFilter === 'All' || item.category === ministryFilter) && `${item.name} ${item.summary} ${item.detail}`.toLowerCase().includes(query)); return visibleMinistries.length ? visibleMinistries.map((item) => <Pressable key={item.name} onPress={() => openMinistry(item)} style={styles.listCard}><View style={styles.smallIcon}><MaterialCommunityIcons name={item.icon} size={21} color="#5965f8" /></View><View style={{ flex: 1 }}><Text style={styles.listTitle}>{item.name}</Text><Text style={styles.listText}>{item.summary}</Text></View><Ionicons name="chevron-forward" size={18} color="#9aa0b5" /></Pressable>) : <View style={styles.eventsEmpty}><View style={styles.smallIcon}><Ionicons name="people-outline" size={20} color="#5965f8" /></View><Text style={styles.listTitle}>No ministries match your search</Text><Text style={[styles.listText, {textAlign:'center'}]}>Try another word or choose All.</Text><Pressable onPress={() => { setMinistrySearch(''); setMinistryFilter('All'); }} style={styles.eventsSeeAll}><Text style={styles.eventsSeeAllText}>CLEAR FILTERS</Text></Pressable></View>; })()}
